// Writes the columns of thread.title.update, thread.close and thread.reopen and the version.
func (q *Queries) SaveThread(ctx context.Context, arg SaveThreadParams) error {
	_, err := q.db.Exec(ctx, saveThread,
		arg.Title,
		arg.TitleSource,
		arg.State,
		arg.ClosedAt,
		arg.ClosedBy,
		arg.Version,
		arg.ID,
	)
	return err
}

const shareThread = `-- name: ShareThread :one
SELECT id, channel_id, kind, parent_message_id, title, title_source, state, closed_at, closed_by, operator_agent_id,
    last_message_seq, unread_floor_seq, last_activity_at, message_count, created_by, created_at, moved_at, version
FROM threads WHERE id = $1 FOR SHARE
`

type ShareThreadRow struct {
	ID              pgtype.UUID
	ChannelID       pgtype.UUID
	Kind            string
	ParentMessageID pgtype.UUID
	Title           string
	TitleSource     string
	State           string
	ClosedAt        pgtype.Timestamptz
	ClosedBy        pgtype.UUID
	OperatorAgentID pgtype.UUID
	LastMessageSeq  int64
	UnreadFloorSeq  int64
	LastActivityAt  pgtype.Timestamptz
	MessageCount    int32
	CreatedBy       pgtype.UUID
	CreatedAt       pgtype.Timestamptz
	MovedAt         pgtype.Timestamptz
	Version         int64
}

// The thread held against a concurrent move while sync copies its channel (M1-61).
func (q *Queries) ShareThread(ctx context.Context, id pgtype.UUID) (ShareThreadRow, error) {
	row := q.db.QueryRow(ctx, shareThread, id)
	var i ShareThreadRow
	err := row.Scan(
		&i.ID,
		&i.ChannelID,
		&i.Kind,
		&i.ParentMessageID,
		&i.Title,
		&i.TitleSource,
		&i.State,
		&i.ClosedAt,
		&i.ClosedBy,
		&i.OperatorAgentID,
		&i.LastMessageSeq,
		&i.UnreadFloorSeq,
		&i.LastActivityAt,
		&i.MessageCount,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.MovedAt,
		&i.Version,
	)
	return i, err
}

const threadCounters = `-- name: ThreadCounters :many
SELECT id, channel_id, last_message_seq, unread_floor_seq
FROM threads
WHERE channel_id = ANY($1::uuid[]) AND last_message_seq > unread_floor_seq
ORDER BY id
`

type ThreadCountersRow struct {
	ID             pgtype.UUID
	ChannelID      pgtype.UUID
	LastMessageSeq int64
	UnreadFloorSeq int64
}

// The counters of the snapshot of sync (M1-63, 07 section 7.4 "unread counter"): the threads of
// the given channels (the visible set of the caller) with a message above unread_floor_seq, so
// somebody may have something unread there. The read positions live in sync, which combines both
// in Go (07 7.4 rule 6, no join across modules).
func (q *Queries) ThreadCounters(ctx context.Context, channelIds []pgtype.UUID) ([]ThreadCountersRow, error) {
	rows, err := q.db.Query(ctx, threadCounters, channelIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ThreadCountersRow
	for rows.Next() {
		var i ThreadCountersRow
		if err := rows.Scan(
			&i.ID,
			&i.ChannelID,
			&i.LastMessageSeq,
			&i.UnreadFloorSeq,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const threadIDsOfChannels = `-- name: ThreadIDsOfChannels :many
SELECT id FROM threads WHERE channel_id = ANY ($1::uuid[]) ORDER BY id
`

// Every thread of the channels, ascending: the targets of the cleanup of notification
// preferences when a channel or space is archived (M3-18).
func (q *Queries) ThreadIDsOfChannels(ctx context.Context, channelIds []pgtype.UUID) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, threadIDsOfChannels, channelIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
